    // Initial Loading Simulation
    setTimeout(() => {
        setIsLoading(false);
        setShowIntro(false);
    }, 2500);
  }, []);

  useEffect(() => {
    if (darkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [darkMode]);

  const handlePageChange = (page: string) => {
    setIsLoading(true);
    setTimeout(() => {
      setPage(page);
