  );

  const renderStep6 = () => {
    if (!vehicle.selectedProvider) return null;
    const prov = vehicle.selectedProvider;
    const finalTotal = Math.max(0, totalBeforeFees + prov.adminFee + STAMP_DUTY - (vehicle.discountAmount || 0));

