  const renderStep7 = () => {
    const prov = vehicle.selectedProvider;
    const finalTotal = prov ? Math.max(0, totalBeforeFees + prov.adminFee + STAMP_DUTY - (vehicle.discountAmount || 0)) : 0;

    if (showXendit) {
