      <Navbar 
        lang={lang} 
        setLang={setLang} 
        darkMode={darkMode} 
        setDarkMode={setDarkMode} 
        currentPage={currentPage}
        setPage={handlePageChange}
      />
      <main className="flex-grow relative">
        {renderContent()}
      </main>

      {currentPage === 'home' && (
        <Footer lang={lang} setPage={handlePageChange} />
      )}
    </div>
  );
}

