// --- CLAIM WITH AI ---

const ClaimWithAI = ({ lang }: { lang: Language }) => {
  const [image, setImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<any>(null);

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
       const reader = new FileReader();
       reader.onloadend = async () => {
          const base64 = reader.result as string;
          setImage(base64);
          setAnalyzing(true);
          const res = await analyzeClaimPhoto(base64);
          setResult(res.data);
          setAnalyzing(false);
       };
       reader.readAsDataURL(e.target.files[0]);
    }
  };

  return (
    <div className="max-w-2xl mx-auto py-12 px-4 animate-fade-in">
       <h2 className="text-3xl font-bold mb-6 text-center">{lang === Language.EN ? 'Instant Claim Analysis' : 'Analisa Klaim Instan'}</h2>

       {!image ? (
         <div className="border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-3xl p-12 text-center hover:border-primary-500 transition-colors bg-white dark:bg-white/5 relative">
            <input type="file" accept="image/*" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
            <Camera className="mx-auto text-gray-400 mb-4" size={48} />
            <p className="text-lg font-bold">{lang === Language.EN ? 'Upload Damage Photo' : 'Unggah Foto Kerusakan'}</p>
            <p className="text-gray-500">{lang === Language.EN ? 'AI will estimate repair costs instantly.' : 'AI akan mengestimasi biaya perbaikan secara instan.'}</p>
         </div>
       ) : (
         <div className="space-y-8">
            <img src={image} alt="Damage" className="w-full rounded-2xl shadow-lg max-h-80 object-cover" />

            {analyzing ? (
               <div className="text-center py-8">
                  <div className="w-12 h-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                  <p className="font-bold text-lg animate-pulse">{lang === Language.EN ? 'AI is analyzing damage...' : 'AI sedang menganalisis kerusakan...'}</p>
               </div>
            ) : result ? (
               <div className="bg-white dark:bg-[#111] rounded-2xl border border-gray-200 dark:border-white/10 p-6 shadow-xl animate-pop-in">
                  <div className={`inline-block px-4 py-1 rounded-full text-sm font-bold mb-4 ${result.severity === 'High' ? 'bg-red-100 text-red-600' : 'bg-yellow-100 text-yellow-600'}`}>
                     Severity: {result.severity}
                  </div>
                  <h3 className="text-2xl font-bold mb-2">{result.estimatedCost}</h3>
                  <p className="text-gray-500 mb-6">{result.recommendation}</p>

                  <div className="space-y-2">
                     <p className="font-bold text-sm text-gray-400 uppercase tracking-wider">Detected Damage</p>
                     <ul className="list-disc list-inside space-y-1">
                        {result.damagePoints.map((p:string, i:number) => <li key={i}>{p}</li>)}
                     </ul>
                  </div>
               </div>
            ) : null}

            {!analyzing && (
               <button onClick={() => {setImage(null); setResult(null)}} className="w-full py-4 rounded-xl border-2 border-gray-200 dark:border-gray-800 font-bold">
                  {lang === Language.EN ? 'Analyze Another' : 'Analisa Lainnya'}
               </button>
            )}
         </div>
       )}
    </div>
  );
};

