          <button onClick={() => setPaState({...paState, type: 'STUDENT'})} className={`p-4 border-2 rounded-xl font-bold ${paState.type === 'STUDENT' ? 'border-primary-500 bg-primary-50' : 'border-gray-200'}`}>Student</button>
      </div>
      <button onClick={() => setStep(2)} className="w-full btn-luxury">View Plans</button>
