  const renderStep2 = () => (
    <div className="space-y-4 animate-fade-in">
       {plans.map((p: any) => (
         <div key={p.code} onClick={() => setStep(3)} className="p-4 border-2 rounded-xl hover:border-primary-500 cursor-pointer flex justify-between items-center">
           <div><h4 className="font-bold">Plan {p.code}</h4><p className="text-sm">Benefit: {p.benefit}</p></div>
           <p className="font-bold text-primary-600">Rp {p.premium.toLocaleString()}</p>
         </div>
       ))}
