const TravelInsuranceWizard = ({ lang, setPage }: { lang: Language, setPage: (p:string) => void }) => {
  const [step, setStep] = useState(1);
  const [travel, setTravel] = useState<TravelState>({
    destination: '',
    region: 'INTERNATIONAL',
    startDate: '',
    endDate: '',
    duration: 0,
    tripType: 'SINGLE',
    participantType: 'INDIVIDUAL',
    travelers: { adults: 1, children: 0, details: [] },
    selectedPlan: null
  });

  const calculateDuration = (start: string, end: string) => {
    if (!start || !end) return 0;
    const s = new Date(start);
    const e = new Date(end);
    const diff = e.getTime() - s.getTime();
    return Math.ceil(diff / (1000 * 3600 * 24)) + 1;
  };

  useEffect(() => {
    setTravel(prev => ({ ...prev, duration: calculateDuration(prev.startDate, prev.endDate) }));
  }, [travel.startDate, travel.endDate]);

  const getPremium = (plan: TravelPlanType) => {
    const regionData = TRAVEL_PRICING[travel.region] as any;
    const typeKey = travel.participantType; 
    const pricingTable = (travel.region === 'INBOUND' || travel.region === 'DOMESTIC') && typeKey === 'FAMILY' 
      ? regionData['INDIVIDUAL'] 
      : regionData[typeKey];
    if (!pricingTable) return 0;
    const duration = travel.duration;
    const band = pricingTable.find((b: any) => duration <= b.maxDays) || pricingTable[pricingTable.length - 1];
    let basePrice = band.rates[plan] || 0;
    if (travel.participantType === 'FAMILY' && travel.travelers.children > 2) {
      const extraChildren = travel.travelers.children - 2;
      const indTable = regionData['INDIVIDUAL'];
      const indBand = indTable.find((b: any) => duration <= b.maxDays) || indTable[indTable.length - 1];
      const indPrice = indBand.rates[plan] || 0;
      basePrice += (indPrice * extraChildren);
    }
    return basePrice;
  };

  const renderStep1 = () => (
    <div className="space-y-6 animate-fade-in">
      <h3 className="text-xl font-bold mb-4">{lang === Language.EN ? 'Trip Details' : 'Detail Perjalanan'}</h3>
      <div className="grid md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium mb-2">{lang === Language.EN ? 'Destination Region' : 'Wilayah Tujuan'}</label>
          <select className="w-full p-4 rounded-xl border-2 border-gray-200 dark:border-gray-800 bg-transparent" value={travel.region} onChange={(e) => setTravel({...travel, region: e.target.value as TravelRegion})}>
            <option value="INTERNATIONAL">International (Outbound)</option>
            <option value="DOMESTIC">Domestic (Indonesia)</option>
            <option value="INBOUND">Inbound (To Indonesia)</option>
          </select>
        </div>
        <FloatingLabelInput label={lang === Language.EN ? 'Destination City/Country' : 'Kota/Negara Tujuan'} value={travel.destination} onChange={(e:any) => setTravel({...travel, destination: e.target.value})} />
      </div>
      <div className="grid md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium mb-2">{lang === Language.EN ? 'Start Date' : 'Tanggal Mulai'}</label>
          <input type="date" className="w-full p-4 rounded-xl border-2 border-gray-200 dark:border-gray-800 bg-transparent dark:text-white" value={travel.startDate} onChange={(e) => setTravel({...travel, startDate: e.target.value})} />
        </div>
        <div>
          <label className="block text-sm font-medium mb-2">{lang === Language.EN ? 'End Date' : 'Tanggal Selesai'}</label>
          <input type="date" className="w-full p-4 rounded-xl border-2 border-gray-200 dark:border-gray-800 bg-transparent dark:text-white" value={travel.endDate} onChange={(e) => setTravel({...travel, endDate: e.target.value})} />
        </div>
      </div>
      <button disabled={!travel.duration || !travel.destination} onClick={() => setStep(2)} className="w-full btn-luxury">{lang === Language.EN ? 'View Plans' : 'Lihat Paket'}</button>
    </div>
  );

  const renderStep2 = () => {
    const plans = travel.region === 'INTERNATIONAL' ? ['PLATINUM', 'GOLD', 'ASIA_EXTRA'] : ['GARUDA_1', 'GARUDA_2'];
    return (
      <div className="space-y-6 animate-fade-in">
        <h3 className="text-xl font-bold mb-4">{lang === Language.EN ? 'Select Plan' : 'Pilih Paket'}</h3>
        {plans.map((planKey) => (
          <div key={planKey} className="p-6 rounded-2xl border-2 border-gray-200 dark:border-gray-800 hover:border-primary-500 cursor-pointer bg-white dark:bg-white/5" onClick={() => { setTravel({...travel, selectedPlan: planKey as TravelPlanType}); setStep(3); }}>
            <h4 className="text-xl font-black uppercase">{planKey.replace('_', ' ')}</h4>
            <p className="text-2xl font-bold text-primary-600">Rp {getPremium(planKey as TravelPlanType).toLocaleString()}</p>
          </div>
        ))}
      </div>
    );
  };

  const renderStep5 = () => (
    <div className="animate-pop-in text-center py-12">
      <CheckCircle2 size={48} className="mx-auto text-green-500 mb-6"/>
      <h2 className="text-4xl font-bold mb-4">{lang === Language.EN ? 'Success!' : 'Berhasil!'}</h2>
      <button onClick={() => setPage('home')} className="btn-luxury px-12">Home</button>
    </div>
  );

  return (
    <div className="max-w-3xl mx-auto py-12 px-4">
      {step < 5 && (
        <div className="mb-8 flex items-center gap-4">
          <button onClick={() => step > 1 ? setStep(step-1) : setPage('products')} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800"><ChevronLeft/></button>
          <div className="flex-1"><h2 className="text-2xl font-bold">Travel Insurance</h2><div className="w-full bg-gray-200 h-1.5 mt-2 rounded-full"><div className="bg-primary-500 h-full" style={{ width: `${(step/5)*100}%` }}></div></div></div>
          <span className="text-sm font-bold text-gray-400">{step}/5</span>
        </div>
      )}
      {step === 1 && renderStep1()}
      {step === 2 && renderStep2()}
      {step === 3 && <div className="space-y-6 animate-fade-in"><h3 className="text-xl font-bold">Details</h3><button onClick={() => setStep(4)} className="w-full btn-luxury">Next</button></div>}
      {step === 4 && <div className="space-y-6 animate-fade-in"><h3 className="text-xl font-bold">Summary</h3><button onClick={() => setStep(5)} className="w-full btn-luxury">Pay</button></div>}
      {step === 5 && renderStep5()}
    </div>
  );
};

