const ClaimWithAI = ({ lang }: { lang: Language }) => {
  const [image, setImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<any>(null);
  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
       const reader = new FileReader();
       reader.onloadend = async () => {
          const base64 = reader.result as string;
          setImage(base64);
          setAnalyzing(true);
          const res = await analyzeClaimPhoto(base64);
          setResult(res.data);
          setAnalyzing(false);
       };
       reader.readAsDataURL(e.target.files[0]);
    }
  };
  return (
    <div className="max-w-2xl mx-auto py-12 px-4 animate-fade-in">
       <h2 className="text-3xl font-bold mb-6 text-center">{lang === Language.EN ? 'Instant Claim Analysis' : 'Analisa Klaim Instan'}</h2>
       {!image ? (
         <div className="border-2 border-dashed border-gray-300 dark:border-gray-700 rounded-3xl p-12 text-center relative bg-white dark:bg-white/5">
            <input type="file" accept="image/*" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
            <Camera className="mx-auto text-gray-400 mb-4" size={48} />
            <p className="text-lg font-bold">Upload Damage Photo</p>
         </div>
       ) : (
         <div className="space-y-8">
            <img src={image} alt="Damage" className="w-full rounded-2xl shadow-lg max-h-80 object-cover" />
            {analyzing ? <p className="text-center animate-pulse">AI is analyzing...</p> : result && <div className="bg-white dark:bg-[#111] rounded-2xl p-6 border shadow-xl"><h3 className="text-2xl font-bold mb-2">{result.estimatedCost}</h3><p className="text-gray-500">{result.recommendation}</p></div>}
            {!analyzing && <button onClick={() => setImage(null)} className="w-full py-4 rounded-xl border-2 font-bold">Analyze Another</button>}
         </div>
       )}
    </div>
  );
};

